#include<bits/stdc++.h>
using namespace std;
const int N = 505;
int n, m, M;
long long dp[N], f[N], C[N][N];
long long d[N][N], fd[N][N];

// Helper to access fd/d with fallback for negative index
inline long long get_fd(int i, int j, int k) {
    return (i-k-1 >= 0) ? fd[i-k-1][j-k] : 1;
}
inline long long get_d(int i, int j, int k) {
    return (i-k-1 >= 0) ? d[i-k-1][j-k] : 0;
}

int main() {
    scanf("%d %d %d", &n, &m, &M);
    f[0] = 1;
    for (int i = 0; i <= n; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j)
            C[i][j] = (C[i-1][j] + C[i-1][j-1]) % M;
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            f[i] = (f[i] + f[j-1] * f[i-j] % M * C[i-1][j-1] % M * (i+1)) % M;
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            int s = 0;
            for (int k = 1; k <= i; ++k) s += abs(k-j);
            dp[i] = (dp[i] + dp[j-1] * f[i-j] % M * C[i-1][j-1] % M * (i+1) 
                     + f[j-1] * dp[i-j] % M * C[i-1][j-1] % M * (i+1) 
                     + s * f[j-1] % M * f[i-j] % M * C[i-1][j-1]) % M;
        }
    }
    fd[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= min(m, i); ++j) {
            fd[i][j] = fd[i-1][j];
            d[i][j] = d[i-1][j];
            for (int k = 1; k <= j; ++k) {
                long long fdPrev = get_fd(i, j, k);
                long long dPrev = get_d(i, j, k);
                fd[i][j] = (fd[i][j] + fdPrev * f[k] % M * C[j][k]) % M;
                d[i][j] = (d[i][j] + (fdPrev * dp[k] + dPrev * f[k]) % M * C[j][k]) % M;
            }
        }
    }
    cout << (d[n][m] % M + M) % M;
    return 0;
}
